/* stack_table.h: BCC.EXE's stack as measured over the corpus (stack_table.c, generated by
   tools/genstack.py from tools/record.py --sp; native/stack.c says how it is used) */
#ifndef STACK_TABLE_H
#define STACK_TABLE_H
#include "port.h"

typedef struct {
    void *fn;           /* a translated function */
    u16 usual_drop;     /* its most common SP drop from a caller, for pairs never measured */
    u16 check;          /* for the functions with a stack check: what its frame holds at the
                           check, which compares SP with 8F0Ch */
} StackFunction;

typedef struct {
    u16 callee, caller; /* indexes into STACK_FUNCTIONS */
    u16 drop;           /* the caller's SP at its entry less the callee's at its entry */
} StackDrop;

extern const StackFunction STACK_FUNCTIONS[];
extern const int STACK_FUNCTION_COUNT;
extern const StackDrop STACK_DROPS[];
extern const int STACK_DROP_COUNT;
#endif
